<script setup>
import {ref,reactive,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {templates,layouts,slideLayout} from './templates.js'
import CoursewareEvidence from './CoursewareEvidence.vue'
import EmphasisText from './EmphasisText.vue'
import AccountSettings from './AccountSettings.vue'
import CoursewareStudio from './CoursewareStudio.vue'
const token=ref(sessionStorage.getItem('edu_token')||''),me=ref(null),health=ref({}),tenants=ref([]),tenant=ref(0)
const page=ref('courseware'),tab=ref('outline'),busy=ref(false),error=ref(''),notice=ref(''),loginForm=reactive({username:'teacher',password:''})
const billing=ref({available:0,reserved:0,products:[],orders:[],ledger:[]}),tasks=ref([]),docs=ref([]),members=ref([]),dashboard=ref({tasks:[],usage:[]})
const task=ref(null),draft=ref(null),accept=ref(false),selectedSlide=ref(0),sources=ref([]),query=ref(''),url=ref(''),webPreview=ref(null),videoURL=ref(''),showProcess=ref(false),history=ref([]),historyOpen=ref(false),historyDraft=ref(null)
const historyOffset=ref(0),historyMore=ref(false)
const processGroups=computed(()=>[...new Set((task.value?.events||[]).map(e=>e.stage))].map(stage=>({stage,title:({queued:'任务预留',edited:'内容修改',restored:'版本恢复',reviewed:'辅助评审',repairing:'自动修复与排版检查'})[stage]||labels[stage]||stage,events:task.value.events.filter(e=>e.stage===stage)})))
const form=reactive({topic:'浮力',subject:'物理',grade:'八年级',textbook:'人教版',objectives:'理解浮力的方向与大小，能运用阿基米德原理解决简单问题。',pages:12,theme:'forest',use_kb:true,use_web:true,source_task_id:'',animation_engine:'manim'})
const videoAvailable=computed(()=>health.value.mode!=='sample'&&health.value.animation_video_configured===true)
const videoDuration=computed(()=>Number.isInteger(health.value.animation_video_duration)&&health.value.animation_video_duration>0?health.value.animation_video_duration:null)
const submitting=ref(false),outputPanel=ref(null),worksQuery=ref(''),worksType=ref(''),worksStatus=ref(''),worksOffset=ref(0),worksMore=ref(false),worksLoading=ref(false),workItems=ref([]),renameItem=ref(null),renameTitle=ref(''),deleteItem=ref(null)
const terminal=['succeeded','degraded','failed','cancelled']
const generating=computed(()=>submitting.value||!!task.value&&!terminal.includes(task.value.status)&&!['awaiting_preview','awaiting_confirmation','awaiting_acceptance'].includes(task.value.status))
const studioMode=computed(()=>page.value==='courseware'&&task.value?.type==='courseware'&&task.value?.input?.preview_first===true)
const progressStep=computed(()=>finished.value?3:task.value?.status==='awaiting_confirmation'?1:['confirmed','rendering'].includes(task.value?.status)?2:0)
const currentSlide=computed(()=>draft.value?.slides[selectedSlide.value])
const newMember=reactive({username:'',name:'',password:''})
const nav=[['courseware','▤','课件工作台'],['animation','◈','教学动画'],['knowledge','▧','知识与来源'],['tasks','◷','我的作品'],['billing','◇','套餐与账单'],['dashboard','▥','用量与评测']]
const labels={pending:'等待研究',researching:'研究资料中',awaiting_preview:'待审核前三页',expand_pending:'等待生成剩余页',expanding:'生成剩余课件中',awaiting_confirmation:'待教师确认',confirmed:'等待制作',rendering:'制作文件中',awaiting_acceptance:'待成品验收',succeeded:'已完成',degraded:'简化交付',failed:'待处理',cancelled:'已取消'}
const worksView=ref('works')
const worksStatusOptions=computed(()=>Object.fromEntries(Object.entries(labels).filter(([state])=>worksView.value==='history'||(['failed','cancelled'].includes(state)===(worksView.value==='interrupted')))))
const price=computed(()=>page.value==='animation'?40:20),finished=computed(()=>['succeeded','degraded'].includes(task.value?.status))
const canEdit=computed(()=>!busy.value&&(task.value?.status==='awaiting_confirmation'||(finished.value&&task.value?.type!=='animation'))),title=computed(()=>nav.find(x=>x[0]===page.value)?.[2]||(page.value==='account'?'个人账户':'企业管理'))
const can=(p)=>me.value?.role==='admin'||me.value?.permissions?.includes(p)
const coursewarePaused=computed(()=>task.value?.type==='courseware'&&task.value.status==='failed')
const statusText=t=>t?.status==='failed'&&t?.type==='courseware'?'待继续制作':labels[t?.status]||t?.status
function passwordChanged(){token.value='';me.value=null;sessionStorage.removeItem('edu_token');clearTask();loginForm.password='';notice.value='密码已更新，请使用新密码重新登录。';page.value='courseware'}
async function retryCourseware(){await run(async()=>{const v=await api('/tasks/'+task.value.id+'/retry','POST',{});await selectTask(v.id);notice.value='已继续制作；原任务未扣款，本次重新预留20积分，成功交付后结算。';await focusOutput()})}
async function api(path,method='GET',data){
 const writesCourseware=path==='/tasks'&&data?.type==='courseware'||task.value?.type==='courseware'&&/^\/tasks\/[^/]+\/(confirm|edit|rewrite|retry|revisions\/\d+\/restore)$/.test(path)
 if(method==='POST'&&writesCourseware&&health.value.courseware_media_version!=='media-v1')throw Error('课件服务尚未更新，请重启后端与排版服务并刷新页面后再提交。当前编辑内容已保留。')
 const opts={method,headers:{}};if(token.value)opts.headers.Authorization='Bearer '+token.value;if(data instanceof FormData)opts.body=data;else if(data!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}const r=await fetch('/api'+path,opts);if(!r.ok){const v=await r.json().catch(()=>({}));if(r.status===401&&path!='/auth/login'){token.value='';me.value=null;sessionStorage.removeItem('edu_token')}throw Error(v.message||'请求失败：'+r.status)}return r.status===204?null:r.json()
}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function refreshAccount(){[me.value,billing.value,tasks.value]=await Promise.all([api('/auth/me'),api('/billing'),api('/tasks')]);tenant.value=me.value.tenant_id}
async function login(){await run(async()=>{const v=await api('/auth/login','POST',loginForm);token.value=v.token;sessionStorage.setItem('edu_token',v.token);tenants.value=v.tenants;await refreshAccount();loginForm.password=''})}
async function logout(){await run(async()=>{await api('/auth/logout','POST',{});token.value='';me.value=null;clearTask();sessionStorage.removeItem('edu_token')})}
async function switchTenant(){await run(async()=>{const v=await api('/auth/switch-tenant','POST',{tenant_id:Number(tenant.value)});token.value=v.token;sessionStorage.setItem('edu_token',v.token);clearTask();docs.value=[];sources.value=[];workItems.value=[];worksRequest++;page.value='courseware';await refreshAccount()})}
let selectionVersion=0,worksRequest=0,polling=false
function clearTask(){selectionVersion++;task.value=null;draft.value=null;history.value=[];historyOpen.value=false;historyDraft.value=null;showProcess.value=false;renameItem.value=null;deleteItem.value=null;if(videoURL.value){URL.revokeObjectURL(videoURL.value);videoURL.value=''}}
async function selectTask(id,{poll=false}={}){
 if(poll&&polling)return
 const version=poll?selectionVersion:++selectionVersion
 if(poll)polling=true
 let v
 try{v=await api('/tasks/'+id)}finally{if(poll)polling=false}
 if(version!==selectionVersion||(poll&&task.value?.id!==id)||(task.value?.id===id&&v.revision<task.value.revision))return
 if(!poll&&task.value?.id!==id&&v.type==='animation')form.animation_engine=v.input?.animation_engine==='ark'?'ark':'manim'
 if(task.value?.id!==id){if(videoURL.value)URL.revokeObjectURL(videoURL.value);videoURL.value=''}
 if(task.value?.id!==id){history.value=[];historyOpen.value=false;historyDraft.value=null}
 if(task.value?.id!==id||task.value?.revision!==v.revision||(!draft.value&&v.result?.slides)){draft.value=v.result?.slides?structuredClone(v.result):null;selectedSlide.value=0;accept.value=false}
 if(draft.value&&v.result?.evaluation)draft.value.evaluation=v.result.evaluation
 task.value=v
 if(v.type==='animation'&&v.status==='awaiting_acceptance'&&!videoURL.value)await previewAnimation(id,version)
 if(!poll)await refreshAccount();else if(terminal.includes(v.status))billing.value=await api('/billing')
}
async function focusOutput(){await nextTick();const panel=outputPanel.value?.$el||outputPanel.value;panel?.scrollIntoView({behavior:'smooth',block:'start'});panel?.focus({preventScroll:true})}
function newWork(kind){clearTask();page.value=kind;form.source_task_id='';if(kind==='animation'&&form.pages>12)form.pages=8}
async function openWork(t){await run(async()=>{page.value=t.type==='animation'?'animation':'courseware';await nextTick();await selectTask(t.id);const v=task.value;if(v?.id===t.id){for(const k of ['topic','subject','grade','textbook','objectives','use_kb','use_web'])if(v.input[k]!==undefined)form[k]=v.input[k];form.source_task_id=v.input.source_task_id||'';form.pages=v.input.pages||8;form.theme=v.result?.theme||v.input.theme||'forest';}tab.value='outline';await focusOutput()})}
async function loadWorks(reset=false){if(health.value.works_view_version!=='views-v1')worksView.value='history';if(reset)worksOffset.value=0;const request=++worksRequest;worksLoading.value=true;try{const params=new URLSearchParams({view:worksView.value,q:worksQuery.value,type:worksType.value,status:worksStatus.value,offset:String(worksOffset.value),limit:'51'});const rows=await api('/tasks?'+params);if(request===worksRequest){workItems.value=rows.slice(0,50);worksMore.value=rows.length>50}}finally{if(request===worksRequest)worksLoading.value=false}}
async function renameWork(){await run(async()=>{await api('/tasks/'+renameItem.value.id,'PATCH',{title:renameTitle.value.trim()});renameItem.value=null;await loadWorks();await refreshAccount();notice.value='作品名称已更新。'})}
async function deleteWork(){await run(async()=>{const id=deleteItem.value.id;await api('/tasks/'+id,'DELETE');deleteItem.value=null;if(task.value?.id===id)clearTask();await loadWorks();if(!workItems.value.length&&worksOffset.value){worksOffset.value-=50;await loadWorks()}await refreshAccount();notice.value='作品已删除，历史账单保留。'})}
async function create(){await run(async()=>{
 if(page.value==='courseware'&&health.value.courseware_studio_version!=='studio-v1')throw Error('分阶段课件服务尚未更新，请重启服务并刷新页面。')
 if(page.value==='animation'&&form.animation_engine==='ark'&&!videoAvailable.value)throw Error(health.value.mode==='sample'?'本地示例模式不支持情境视频':'尚未配置视频服务')
 submitting.value=true;clearTask();tab.value='outline';await focusOutput()
 try{const kind=page.value==='animation'?'animation':'courseware';const v=await api('/tasks','POST',{...form,animation_engine:kind==='animation'?form.animation_engine:undefined,pages:kind==='animation'?Math.min(form.pages,12):form.pages,source_task_id:kind==='animation'?form.source_task_id:'',type:kind,preview_first:kind==='courseware',idempotency_key:crypto.randomUUID()});await selectTask(v.id);notice.value='任务已提交，当前页面会自动更新。方案完成后请先审核，再确认制作。'}finally{submitting.value=false}
})}
async function previewAnimation(id=task.value?.id,version=selectionVersion){
 const r=await fetch('/api/tasks/'+id+'/download/mp4',{headers:{Authorization:'Bearer '+token.value}});if(!r.ok)throw Error('预览暂不可用');const blob=await r.blob();if(version!==selectionVersion||task.value?.id!==id)return;if(videoURL.value)URL.revokeObjectURL(videoURL.value);videoURL.value=URL.createObjectURL(blob);tab.value='preview'
}
async function acceptAnimation(){await run(async()=>{await api('/tasks/'+task.value.id+'/accept-animation','POST',{revision:task.value.revision,accept:accept.value});await selectTask(task.value.id);notice.value='成品验收完成，积分已结算。'})}
async function viewFrame(index){await run(async()=>{const r=await fetch('/api/tasks/'+task.value.id+'/frames/'+index,{headers:{Authorization:'Bearer '+token.value}});if(!r.ok)throw Error('关键帧不可用');const u=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=u;a.download='frame-'+index+'.jpg';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)})}
async function confirmGeneration(){await run(async()=>{await api('/tasks/'+task.value.id+'/confirm','POST',{result:draft.value,revision:task.value.revision,accept_review:accept.value});await selectTask(task.value.id);await focusOutput()})}
async function cancel(){await run(async()=>{await api('/tasks/'+task.value.id+'/cancel','POST',{});await selectTask(task.value.id)})}
async function save(){await run(async()=>{await api('/tasks/'+task.value.id+'/edit','POST',{result:draft.value,revision:task.value.revision});await selectTask(task.value.id);notice.value='新修订已保存，PPTX已重新导出；未扣积分。'})}
async function loadHistory(offset=0){const id=task.value?.id,rows=await api('/tasks/'+id+'/revisions?offset='+offset);if(task.value?.id!==id)return;history.value=rows.slice(0,50);historyMore.value=rows.length>50;historyOffset.value=offset;historyOpen.value=true;historyDraft.value=null}
async function viewHistory(version){await run(async()=>{const id=task.value.id,v=await api('/tasks/'+id+'/revisions/'+version);if(task.value?.id===id){historyDraft.value=v;historyOpen.value=true}})}
async function restoreHistory(version){if(!window.confirm('恢复将替换当前编辑内容（含未保存修改），并保存为新版本。已保存的旧版仍保留，恢复免费。继续吗？'))return;await run(async()=>{await api('/tasks/'+task.value.id+'/revisions/'+version+'/restore','POST',{revision:task.value.revision});await selectTask(task.value.id);await loadHistory();notice.value='历史版本已恢复并免费重新导出。'})}
async function rewrite(){const instruction=prompt('说明这一页的修改要求（成功后扣5积分）：','让例题更贴近生活，并给出清晰解答');if(!instruction)return;await run(async()=>{const v=await api('/tasks/'+task.value.id+'/rewrite','POST',{instruction,slide:selectedSlide.value,revision:task.value.revision,idempotency_key:crypto.randomUUID()});notice.value='单页修改任务已提交，成功后更新原课件。';await selectTask(v.id)})}
async function download(format,version){await run(async()=>{const r=await fetch('/api/tasks/'+task.value.id+(version?'/revisions/'+version:'')+'/download/'+format,{headers:{Authorization:'Bearer '+token.value}});if(!r.ok)throw Error('文件尚不可用');const blob=await r.blob(),u=URL.createObjectURL(blob);if(format==='mp4'){if(videoURL.value)URL.revokeObjectURL(videoURL.value);videoURL.value=u;tab.value='preview'}const a=document.createElement('a');a.href=u;a.download=(draft.value?.title||'lesson')+(version?'-v'+version:'')+'.'+format;a.click();if(format!=='mp4')setTimeout(()=>URL.revokeObjectURL(u),2000)})}
async function buy(sku){await run(async()=>{const order=await api('/billing/orders','POST',{sku});await api('/billing/orders/'+order.id+'/pay','POST',{});await refreshAccount();notice.value='模拟支付成功，积分已到账；没有发生真实扣款。'})}
async function pay(id){await run(async()=>{await api('/billing/orders/'+id+'/pay','POST',{});await refreshAccount()})}
async function upload(ev){const f=ev.target.files[0];if(!f)return;await run(async()=>{const data=new FormData();data.append('file',f);await api('/documents','POST',data);docs.value=await api('/documents');notice.value='文档已上传，正在后台解析；离开页面不会中断。'});ev.target.value=''}
async function importPage(confirm=false){await run(async()=>{const v=await api('/documents/url','POST',{url:url.value,confirm,hash:webPreview.value?.hash||''});if(confirm){webPreview.value=null;docs.value=await api('/documents');notice.value='网页正文已入库'}else webPreview.value=v})}
async function search(){await run(async()=>{const v=await api('/retrieval/test','POST',{query:query.value,web:false});sources.value=v.sources;if(!sources.value.length)notice.value='未找到相关资料。'})}
async function removeDoc(id){if(!window.confirm('删除此企业共享文档及其切片？已生成作品的来源快照会保留。'))return;await run(async()=>{await api('/documents/'+id,'DELETE');docs.value=await api('/documents')})}
async function addMember(){await run(async()=>{await api('/admin/members','POST',newMember);newMember.username='';newMember.name='';newMember.password='';members.value=await api('/admin/members');notice.value='成员已创建；开通基础套餐后即可生成。'})}
async function assignPackage(m,sku){await run(async()=>{await api('/admin/members/'+m.id+'/package','POST',{sku,idempotency_key:crypto.randomUUID()});members.value=await api('/admin/members');await refreshAccount();notice.value='套餐已分配到该成员独立账户，操作已记录。'})}
async function updateMember(m){await run(async()=>{await api('/admin/members/'+m.id,'PATCH',{active:m.active,permissions:m.permissions});notice.value='成员状态与权限已保存'})}
async function evaluate(){await run(async()=>{const v=await api('/evaluations','POST',{query:query.value||form.topic});notice.value='检索评测已完成：'+JSON.stringify(v.metrics);dashboard.value=await api('/dashboard')})}
function animationFromSlide(){const sl=draft.value?.slides[selectedSlide.value];if(sl){form.source_task_id=finished.value?task.value.id:'';form.topic=draft.value.title;form.objectives=sl.title+'：'+sl.bullets.join('；')}page.value='animation';clearTask();form.pages=Math.min(form.pages,12)}
function date(v){return v?new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'}
let timer,previousFocus,eventController
watch(()=>task.value?.id,id=>{eventController?.abort();if(id){eventController=new AbortController();followEvents(id,eventController.signal)}})
async function followEvents(id,signal){let last='0';while(!signal.aborted&&task.value?.id===id){try{const response=await fetch('/api/tasks/'+id+'/events',{headers:{Authorization:'Bearer '+token.value,'Last-Event-ID':last},signal});if(!response.ok)return;const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(!signal.aborted){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let end;while((end=buffer.indexOf('\n\n'))>=0){const frame=buffer.slice(0,end);buffer=buffer.slice(end+2);const line=frame.split('\n').find(x=>x.startsWith('data: '));const serial=frame.split('\n').find(x=>x.startsWith('id: '));if(serial)last=serial.slice(4);if(line&&task.value?.id===id){const ev=JSON.parse(line.slice(6));if(!task.value.events.some(x=>x.id===ev.id)){task.value.events.push(ev);if(!busy.value)void selectTask(id,{poll:true}).catch(e=>error.value=e.message)}}}}}catch(e){if(signal.aborted)return}if(!signal.aborted)await new Promise(r=>setTimeout(r,2000))}}

watch(()=>!!renameItem.value||!!deleteItem.value,async open=>{if(open){previousFocus=document.activeElement;await nextTick();document.querySelector('.work-dialog input,.work-dialog button')?.focus()}else previousFocus?.focus()})
watch(showProcess,async open=>{if(open){previousFocus=document.activeElement;await nextTick();document.querySelector('[aria-label="关闭过程"]')?.focus()}else previousFocus?.focus()})
function trapDialog(event){if(event.key!=='Tab')return;const nodes=[...event.currentTarget.querySelectorAll('button,summary,a[href],input,textarea,select')].filter(x=>!x.disabled&&x.offsetParent!==null);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
watch(page,async p=>{error.value='';if(task.value&&((p==='animation'&&task.value.type!=='animation')||(p==='courseware'&&task.value.type==='animation'))){clearTask()}try{if(p==='knowledge')docs.value=await api('/documents');if(p==='admin')members.value=await api('/admin/members');if(p==='dashboard')dashboard.value=await api('/dashboard');if(p==='tasks'){await refreshAccount();await loadWorks()}if(p==='billing')await refreshAccount();if(p==='animation'&&form.pages>12)form.pages=8}catch(e){error.value=e.message}})
onMounted(async()=>{try{health.value=await api('/health');if(token.value){tenants.value=await api('/tenants');await refreshAccount()}}catch(e){error.value=e.message}timer=setInterval(async()=>{if(!token.value||busy.value)return;if(page.value==='knowledge'&&docs.value.some(d=>['pending','indexing'].includes(d.status))){try{docs.value=await api('/documents')}catch{}}const t=task.value;if(page.value==='tasks'&&workItems.value.some(x=>!terminal.includes(x.status)&&x.status!=='awaiting_confirmation')){try{await loadWorks()}catch{}}if(t&&(!['succeeded','degraded','failed','cancelled','awaiting_preview','awaiting_confirmation','awaiting_acceptance'].includes(t.status)||(t.status==='succeeded'&&!t.result?.evaluation&&t.type==='courseware'))){try{await selectTask(t.id,{poll:true})}catch(e){error.value=e.message}}},2000)})
onUnmounted(()=>{selectionVersion++;worksRequest++;eventController?.abort();clearInterval(timer);if(videoURL.value)URL.revokeObjectURL(videoURL.value)})
</script>

<template>
 <div v-if="!me" class="login-shell">
  <section class="login-story"><div class="brand"><span class="brand-mark">研</span>备课工坊</div><span class="eyebrow">TEACH LESS PREP. INSPIRE MORE.</span><h1>把时间留给<br><em>真正的教学。</em></h1><p>从可信资料到课堂表达。<br>让每一个好想法，成为一堂好课。</p><div class="orb one"></div><div class="orb two"></div><div class="story-caption">教案 · 可编辑课件 · 概念动画</div></section>
  <form class="login-form" @submit.prevent="login"><span class="eyebrow">WELCOME BACK</span><h2>进入你的备课空间</h2><p class="muted">每位老师独立创作，每份知识共同积累。</p><label>账号<input v-model="loginForm.username" autocomplete="username" required placeholder="请输入账号"></label><label>密码<input v-model="loginForm.password" type="password" autocomplete="current-password" required placeholder="请输入本地配置的密码"></label><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p><button class="primary wide" :disabled="busy">{{busy?'正在登录…':'登录工作台 →'}}</button><p class="fine">{{health.mode==='sample'?'当前为本地示例模式。内容为内置样例，文件与账务流程真实执行。':'真实接口模式 · 私有企业空间'}}</p></form>
 </div>
 <div v-else class="app-shell">
  <aside class="sidebar"><div class="brand"><span class="brand-mark">研</span><div>备课工坊<small>EDUCATOR STUDIO</small></div></div><label class="tenant-select"><span>企业空间</span><select v-model="tenant" @change="switchTenant" :disabled="busy"><option v-for="t in tenants" :key="t.id" :value="t.id">{{t.name}}</option></select></label><div class="nav-caption">教学创作</div><nav aria-label="主导航"><button v-for="n in nav" :key="n[0]" @click="page=n[0]" :class="{active:page===n[0]}" :aria-current="page===n[0]?'page':undefined"><span>{{n[1]}}</span>{{n[2]}}<i v-if="n[0]==='courseware'">主打</i></button><button v-if="can('user.manage')" :class="{active:page==='admin'}" @click="page='admin'"><span>⚙</span>企业管理</button></nav><div class="sidebar-bottom"><div class="quota-card"><span>我的可用积分</span><strong>{{billing.available}}<small> 积分</small></strong><p>预留 {{billing.reserved}} · 成员独立额度</p><button @click="page='billing'">查看套餐与账单 ↗</button></div><div class="profile"><button type="button" class="profile-open" @click="page='account'" aria-label="个人账户设置"><span class="avatar">{{me.name?.slice(-2)}}</span><span><b>{{me.name}}</b><small>{{me.role==='admin'?'企业管理员':'教研成员'}}</small></span></button><button @click="logout" title="退出登录" aria-label="退出登录">↪</button></div></div></aside>
  <main><header class="topbar"><span>工作空间 <span class="crumb">/</span> <b>{{title}}</b></span><div><span class="mode-tag">{{health.mode==='sample'?'本地示例模式':'真实接口模式'}}</span><span class="private-tag">◉ 个人作品私有</span><button class="mobile-account" @click="page='account'" aria-label="个人账户设置">账户</button><button class="mobile-logout" @click="logout">退出</button></div></header>
   <div class="content"><div v-if="error" class="alert error" role="alert">{{error}}<button @click="error=''" aria-label="关闭错误">×</button></div><div v-if="notice" class="alert success" role="status">{{notice}}</div>
    <p v-if="health.status==='ok'&&health.courseware_media_version!=='media-v1'" class="alert" role="status">课件服务尚未加载新版。请重启后端与排版服务后刷新页面，再使用新版课件生成与图解导出。</p>
    <template v-if="['courseware','animation'].includes(page)">
     <div class="page-heading"><div><div class="eyebrow">{{page==='courseware'?'FROM KNOWLEDGE TO CLASSROOM':'MAKE CONCEPTS VISIBLE'}}</div><h1>{{page==='courseware'?'让备课，多一点从容。':'让抽象知识，动起来。'}}</h1><p>{{page==='courseware'?'找资料、理思路、做课件。在一个工作台完成。':form.animation_engine==='ark'?'先审核方案，再生成一段无声情境短片。':'先审核分镜，再生成带文字说明的静音教学动画。'}}</p></div><span class="step-pill">01 研究 <i>→</i> 02 确认 <i>→</i> 03 交付</span></div>
     <div :class="['workbench',{'studio-mode':studioMode}]"><section class="panel config-panel"><div class="panel-title"><span class="icon-square">✦</span><div><h2>{{page==='courseware'?'这次，我们讲什么？':'设计一段概念动画'}}</h2><p>清晰的目标，是好课的开始</p></div></div><p class="assistant-note">{{page==='courseware'?'课件助手独立整理资料、教案与页面内容。':'动画助手独立设计演示方案，按生成方式制作动画。'}}两个助手各自按任务选用模型，方案均由教师审核。</p><form @submit.prevent="create"><label>课题名称<input v-model="form.topic" maxlength="100" required></label><div class="field-row"><label>学科<select v-model="form.subject"><option>物理</option><option>数学</option></select></label><label>年级<select v-model="form.grade" aria-describedby="grade-help"><option>七年级</option><option>八年级</option><option>九年级</option></select></label></div><p id="grade-help" class="field-help">年级用于限定检索范围、调整难度与前置知识；教材内容仍需教师核验。</p><div class="field-row"><label>教材版本<select v-model="form.textbook"><option>人教版</option></select></label><label>{{page==='courseware'?'课件页数':'分镜数量'}}<select v-model.number="form.pages"><option v-for="n in (page==='animation'?[8,10,12]:[8,10,12,16,20])" :key="n" :value="n">{{n}} {{page==='courseware'?'页':'段'}}</option></select></label></div><fieldset v-if="page==='animation'" class="animation-engine"><legend>生成方式</legend>
 <label for="animation-engine" class="sr-only">动画生成方式</label><select id="animation-engine" v-model="form.animation_engine" aria-describedby="animation-engine-help animation-service-note" :disabled="busy||generating">
  <option value="manim">精确教学动画（默认）</option><option value="ark" :disabled="!videoAvailable">情境视频（外部模型）</option>
 </select><p id="animation-engine-help" class="field-help">情境视频适合导入情境；公式和严谨推演建议精确教学动画。</p>
 <p id="animation-service-note" class="field-help"><template v-if="!videoAvailable">{{health.mode==='sample'?'本地示例模式不支持情境视频。':''}}{{health.animation_video_configured!==true?'尚未配置视频服务。':''}}</template><template v-else>情境视频由外部视频模型生成。</template></p>
 <p v-if="form.animation_engine==='ark'" class="field-help animation-duration">单段无声短情境<span v-if="videoDuration"> · 当前服务配置 {{videoDuration}} 秒</span>。云视频时长以实际服务配置为准；不保证与分镜逐一对应，公式内容仍需教师核验。</p>
 <p v-if="form.animation_engine==='ark'" class="field-help animation-billing-note">取消可释放业务积分，但供应商可能已计费；不保证云端退款。</p>
 </fieldset><label>教学目标 <span class="muted">选填</span><textarea v-model="form.objectives" rows="3" maxlength="1000"></textarea></label><p v-if="page==='animation'&&form.source_task_id" class="fine">复用已完成课件的资料快照 <button type="button" @click="form.source_task_id=''">清除关联</button></p><fieldset><legend>资料来源</legend><label class="check-card"><input v-model="form.use_kb" type="checkbox"><span><b>企业知识库</b><small>共享教研材料 · 来源可追溯</small></span><span>▧</span></label><label class="check-card"><input v-model="form.use_web" type="checkbox"><span><b>联网检索</b><small>{{health.mode==='sample'?'示例模式不发起外部搜索':'检索公开网页 · 保留来源'}}</small></span><span>◎</span></label></fieldset><fieldset v-if="page==='courseware'"><legend>课件模板</legend><div class="themes"><label v-for="t in templates" :key="t.id" :class="['theme',t.id,{chosen:form.theme===t.id}]" :title="t.description"><input type="radio" v-model="form.theme" :value="t.id" name="theme"><span class="theme-mini" aria-hidden="true"><b>{{t.mark}}</b><i></i><i></i><em>课堂探索</em></span><strong>{{t.name}}</strong><small>{{t.tag}}</small></label></div></fieldset><div class="cost-line"><span>本次预估</span><b>{{price}} 积分</b></div><button class="primary wide" :disabled="busy||generating||(page==='animation'&&form.animation_engine==='ark'&&!videoAvailable)||!billing.plan||billing.available<price||(!form.use_kb&&!form.use_web)||!can(page==='animation'?'animation.render':'courseware.generate')">{{busy?'正在提交…':generating?'当前任务制作中…':!billing.plan?'请先开通基础套餐':billing.available<price?'可用积分不足':'✦ 开始研究，生成方案'}}</button><p class="fine centered">先预留，确认交付后结算。取消或失败自动释放。</p></form></section>
      <CoursewareStudio v-if="studioMode" ref="outputPanel" :task="task" :api="api" :token="token" :available="billing.available" :refresh="()=>selectTask(task.id)" @process="showProcess=true" @retry="retryCourseware" @new-work="newWork('courseware')" @animation="sl=>{selectedSlide=draft.slides.findIndex(s=>s.id===sl.id);animationFromSlide()}"/>
      <section v-else class="panel output-panel" ref="outputPanel" tabindex="-1" aria-label="当前制作任务" :aria-busy="generating"><div class="output-head"><div><span class="tiny-label">{{task?'当前创作':'创作预览'}}</span><h2>{{task?.display_title||draft?.title||task?.input?.topic||'一堂好课，从这里展开'}}</h2></div><span v-if="task" :class="['status',task.status]">{{statusText(task)}}</span><span v-else class="muted">等待开始</span></div><div v-if="task||submitting" :class="['generation-progress',{working:generating}]" role="status" aria-live="polite">
 <div class="progress-heading"><span v-if="generating" class="spinner" aria-hidden="true"></span><strong>{{submitting?'正在提交制作任务':statusText(task)}}</strong><small v-if="task">{{task.type==='animation'?'教学动画':'课件'}} · {{task.cost}} 积分</small></div>
 <ol class="progress-steps"><li v-for="(step,i) in ['检索与构思','教师审核','制作文件','交付完成']" :key="step" :class="{current:i===progressStep,done:i<progressStep}"><span>{{i<progressStep?'✓':i+1}}</span>{{step}}</li></ol>
 <p v-if="!coursewarePaused">{{task?.error||(submitting?'正在创建任务，请稍候…':task?.status==='awaiting_confirmation'?'方案已准备好。可编辑教案、大纲和备注，审核后点击下方“确认方案”。':finished?'作品已完成，可以直接预览、编辑或下载。':task?.status==='cancelled'?'任务已取消，预留积分已释放。':task?.events?.at(-1)?.message||'正在检索资料并组织教学内容，本页面将自动更新。')}}</p>
 <div v-if="coursewarePaused" class="recovery-actions"><p>{{draft?'上次制作已暂停，草稿已保存，可继续审核并制作。':'上次制作已暂停，课题设置已保留，可继续整理方案。'}}预留积分已释放，本次未扣款。</p><button class="primary" @click="retryCourseware" :disabled="busy||billing.available<20||!can('courseware.generate')">继续制作</button><small>重新预留20积分，成功交付后结算。</small><details><summary>查看原因与处理建议</summary><p>{{task.error}}</p></details></div>
 </div><div class="tabs" role="tablist"><button v-for="t in [['lesson','教案'],['outline','大纲与编辑'],['preview','课件预览'],['sources','资料来源']]" :key="t[0]" role="tab" :aria-selected="tab===t[0]" :class="{selected:tab===t[0]}" @click="tab=t[0]">{{t[1]}}<span v-if="t[0]==='sources'&&task">{{task.sources?.length||0}}</span></button></div>
       <div v-if="!draft" class="empty-work"><div class="paper-stack"><div></div><div><span>LESSON PLAN</span><b>{{coursewarePaused?'可以继续制作':task?'正在准备教学方案':'留出思考的空间'}}</b><i></i><i></i><i></i><em>✦</em></div></div><h3>{{page==='animation'?(task?'资料 → 演示目标 → 动画方案':'从一个概念，到一段教学演示'):(task?'资料 → 教学目标 → 页面大纲':'从一个课题，到一份完整课件')}}</h3><p>{{coursewarePaused?'课题设置已保留。点击上方“继续制作”恢复流程。':task?.error||'设定教学目标，选择资料来源。我们先整理方案，由你把握课堂的方向。'}}</p><div class="feature-tags"><span>{{page==='animation'?'静音 MP4':'可编辑 PPTX'}}</span><span>引用可追溯</span><span>教师先确认</span></div></div>
       <div v-else class="output-body"><div class="review-note">{{draft.notice}}<span v-if="task.mode==='sample'"> · 内置样例</span></div><div v-if="draft.evaluation" class="fine">{{draft.evaluation.status==='completed'?'辅助模型评审已完成，仍需教师核验':draft.evaluation.reason}}<pre v-if="draft.evaluation.assessment" class="assessment">{{JSON.stringify(draft.evaluation.assessment,null,2)}}</pre></div><section v-if="task.type==='animation'&&draft.animation_quality" class="quality-panel"><b>动画质量检查</b><p v-for="check in draft.animation_quality.checks" :key="check">{{check}}</p><p>{{draft.animation_quality.visual?.reason||'尚未进行成品画面检查'}}</p><p v-for="issue in draft.animation_quality.visual?.issues||[]" :key="issue" class="error">{{issue}}</p><details v-if="draft.animation_quality.frames?.length"><summary>查看动作关键帧（不代替完整播放）</summary><button v-for="f in draft.animation_quality.frames" :key="f.index" @click="viewFrame(f.index)" :disabled="busy">{{f.second.toFixed(1)}}秒 ↓</button></details></section><template v-if="tab==='lesson'"><label>教案内容<textarea class="lesson-editor" v-model="draft.lesson" :readonly="!canEdit" aria-label="教案内容"></textarea></label></template><template v-if="tab==='outline'"><label class="deck-name">课件标题<input v-model="draft.title" :readonly="!canEdit" maxlength="100" aria-label="课件标题"></label><div class="outline-toolbar"><span>{{draft.slides.length}} 页 · 点击文字即可编辑</span><label>模板<select v-model="draft.theme" :disabled="!canEdit"><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name}}</option></select></label><button v-if="finished&&task.type==='courseware'" type="button" @click="run(()=>loadHistory())" :disabled="busy">版本历史</button></div><section v-if="historyOpen" class="panel padded history-panel"><div class="panel-title"><div><h3>版本历史</h3><p class="fine">手工编辑、单页改写和恢复都会保留旧版；恢复不额外扣积分。</p></div><button type="button" @click="historyOpen=false" aria-label="关闭版本历史">×</button></div><p v-if="!history.length" class="empty-small">暂无可恢复版本。</p><article v-for="v in history" :key="v.revision" class="history-row" :data-revision="v.revision"><div><b>修订 {{v.revision}}{{v.revision===task.revision?'（当前）':''}} · {{v.title||'未命名课件'}}</b><small class="block">{{v.pages}} 页 · {{date(v.created_at)}}</small></div><div><button type="button" @click="viewHistory(v.revision)" :disabled="busy">查看内容</button><button :disabled="busy" @click="download('pptx',v.revision)">下载旧版</button><button v-if="can('courseware.generate')" type="button" class="primary" :disabled="busy||v.revision===task.revision" @click="restoreHistory(v.revision)">恢复此版</button></div></article><div class="works-pagination"><button :disabled="busy||!historyOffset" @click="run(()=>loadHistory(historyOffset-50))">上一页版本</button><span>第 {{historyOffset/50+1}} 页</span><button :disabled="busy||!historyMore" @click="run(()=>loadHistory(historyOffset+50))">下一页版本</button></div><details v-if="historyDraft" open class="history-preview"><summary>历史修订 {{historyDraft.revision}} 的内容</summary><h4>{{historyDraft.result.title}}</h4><p class="fine">{{historyDraft.result.lesson}}</p><ol><li v-for="sl in historyDraft.result.slides" :key="sl.title"><b>{{sl.title}}</b><span v-if="sl.bullets?.length">：{{sl.bullets.join('；')}}</span><p class="fine history-notes">{{sl.notes}}</p></li></ol></details></section><article class="outline-slide" v-for="(sl,i) in draft.slides" :key="i"><span class="page-number">{{String(i+1).padStart(2,'0')}}</span><div><input v-model="sl.title" :readonly="!canEdit" :aria-label="'第'+(i+1)+'页标题'" maxlength="70"><textarea :value="sl.bullets.join('\n')" @input="sl.bullets=$event.target.value.split('\n').filter(Boolean)" :readonly="!canEdit" :aria-label="'第'+(i+1)+'页内容'" rows="3"></textarea><div v-if="task.type==='animation'&&sl.scene" class="scene-editor"><label>本幕目标<input v-model="sl.scene.goal" :readonly="!canEdit" maxlength="60"></label><label>时长（秒）<input type="number" v-model.number="sl.scene.duration_sec" :readonly="!canEdit" min="0.1" max="6" step="0.1"></label><label>{{task.input.animation_engine==='ark'&&i>0?'动作节点参考文字（不叠加到视频）':'实际视频字幕'}}<textarea v-model="sl.scene.caption" :readonly="!canEdit" maxlength="40" rows="2"></textarea></label><label>{{task.input.animation_engine==='ark'&&i>0?'节点参考公式（不叠加到视频）':'实际视频公式（Unicode）'}}<input v-model="sl.scene.formula" :readonly="!canEdit" maxlength="40"></label><p class="fine">证据类型：{{({illustration:'教学示意',numeric:'数值验证',proof:'拼图证明'})[sl.scene.evidence]}} · {{task.input.animation_engine==='ark'?'情境视频仅叠加首幕字幕与公式，其余节点用于动作参考。':'视频逐幕使用以上字幕和公式；讲解备注供备课参考。'}}</p><details><summary>图形、动作与约束</summary><pre>{{JSON.stringify({elements:sl.scene.elements,checks:sl.scene.checks},null,2)}}</pre></details></div><details v-if="task.type==='courseware'" class="courseware-media-editor"><summary>公式与图表（实际导出内容）</summary><div class="media-fields"><label>展示公式（LaTeX）<input v-model="sl.formula" :readonly="!canEdit" maxlength="250" placeholder="例如 a^2+b^2=c^2"></label><label>可编辑示意图<select :value="sl.diagram||''" @change="sl.diagram=$event.target.value" :disabled="!canEdit||!!sl.table||!!sl.figure||!!sl.picture"><option value="">无示意图</option><option value="triangle">直角三角形（非拼图证明）</option><option value="buoyancy">浮力方向示意</option></select></label></div><template v-if="sl.chart&&Array.isArray(sl.chart.labels)&&Array.isArray(sl.chart.values)"><div class="media-fields"><label>图表标题及单位<input v-model="sl.chart.title" :readonly="!canEdit" maxlength="80"></label><label>图表类型<select :value="sl.chart.style||'bar'" @change="sl.chart.style=$event.target.value" :disabled="!canEdit"><option value="bar">柱状图 · 类别比较</option><option value="line">折线图 · 等间隔变化</option></select></label></div><div class="media-fields" v-for="(_,j) in sl.chart.labels" :key="j"><label>{{'第'+(j+1)+'项标签'}}<input v-model="sl.chart.labels[j]" :readonly="!canEdit" maxlength="18"></label><label>数值<input type="number" step="any" v-model.number="sl.chart.values[j]" :readonly="!canEdit"></label></div><p class="fine">折线图使用等距类别轴；不等间隔数值不能按真实距离解读。示例数据须在标题和备注中标明，不能冒充实测。</p></template><p class="fine">文字、图表和示意图可在PPT中继续编辑；LaTeX公式以清晰图片导出。网页预览不是实际PPT截图。</p></details><CoursewareEvidence v-if="task.type==='courseware'" :slide="sl" :editable="canEdit"/><div class="slide-edit-options"><label>版式<select v-model="sl.layout" :disabled="!canEdit"><option value="">自动编排</option><option v-for="l in layouts" :key="l[0]" :value="l[0]">{{l[1]}}</option></select></label><details><summary>讲解备注与答案</summary><textarea v-model="sl.notes" :readonly="!canEdit" :aria-label="'第'+(i+1)+'页讲解备注'" rows="5"></textarea></details></div></div><button @click="selectedSlide=i;tab='preview'" :aria-label="'预览第'+(i+1)+'页'">↗</button></article></template><template v-if="tab==='preview'"><video v-if="task.type==='animation'&&videoURL" :src="videoURL" controls class="animation-player"></video><div v-else :class="['slide-preview',draft.theme,'layout-'+slideLayout(currentSlide,selectedSlide)]"><small>备课工坊 · {{draft.title}}</small><span class="preview-kicker">{{layouts.find(l=>l[0]===slideLayout(currentSlide,selectedSlide))?.[1]}} / {{String(selectedSlide+1).padStart(2,'0')}}</span><h2><EmphasisText :text="currentSlide?.title||''" :terms="currentSlide?.emphasis||[]"/></h2><ul><li v-for="(b,i) in currentSlide?.bullets" :key="i"><span class="bullet-index">{{String(i+1).padStart(2,'0')}}</span><EmphasisText :text="b" :terms="currentSlide?.emphasis||[]"/></li></ul><CoursewareEvidence v-if="currentSlide" :slide="currentSlide" preview/><p v-if="currentSlide?.formula" class="preview-formula">{{currentSlide.formula}}</p><div class="preview-footer"><span>布局示意 · 以导出PPTX为准</span><span>{{selectedSlide+1}} / {{draft.slides.length}}</span></div></div><div class="slide-controls"><button @click="selectedSlide=Math.max(0,selectedSlide-1)">← 上一页</button><button @click="animationFromSlide">◈ 以此页设计动画</button><button @click="selectedSlide=Math.min(draft.slides.length-1,selectedSlide+1)">下一页 →</button></div><button v-if="finished&&task.type==='courseware'" @click="rewrite" :disabled="busy||billing.available<5">✦ 单页AI改写 · 5积分</button></template><template v-if="tab==='sources'"><p v-if="!task.sources?.length" class="muted">未找到可引用资料。当前内容需教师核验；确认交付后按普通价格结算。</p><article class="source-card" v-for="s in task.sources" :key="s.id"><span class="source-id">{{s.id}}</span><div><h3>{{s.title}}</h3><small>{{s.kind==='search_summary'?'搜索摘要，未抓取正文':s.kind==='knowledge'?'企业知识库':s.kind==='web_extracted'?'搜索服务提取正文':'公开网页'}} · {{s.location}}</small><p v-if="s.filter" class="fine">{{s.filter.method.includes("vector-candidate")?"向量候选，未按关键词删段":`相关段落保留 ${s.filter.kept} / ${s.filter.total}`}} · {{s.filter.method.includes("rerank")?"已语义重排":s.filter.method.includes("vector-candidate")?"未启用语义重排":"关键词与上下文筛选"}} · 非事实可信度评分<span v-if="s.filter.truncated"> · 篇幅受限，请查看原文</span></p><p>{{s.content}}</p><a v-if="s.url&&/^https?:\/\//.test(s.url)" :href="s.url" target="_blank" rel="noopener noreferrer">查看来源 ↗</a></div></article></template></div>
       <div v-if="task" class="output-actions"><label v-if="task.status==='awaiting_confirmation'&&draft?.needs_review" class="consent"><input type="checkbox" v-model="accept">我已知悉资料需核验，确认{{task.type==='animation'?'成品验收':'完整交付'}}后扣 {{task.cost}} 积分</label><label v-if="task.status==='awaiting_acceptance'" class="consent"><input type="checkbox" v-model="accept">我已完整观看视频，并核对知识、图形、运动和文字；确认后扣 {{task.cost}} 积分</label><div class="action-row"><button v-if="task.status==='awaiting_acceptance'" @click="run(()=>previewAnimation())" :disabled="busy">播放待验收视频</button><button v-if="task.status==='awaiting_acceptance'" class="primary" @click="acceptAnimation" :disabled="busy||!accept||draft.animation_quality?.status!=='awaiting_acceptance'">验收并结算</button><button @click="showProcess=true">◷ 查看制作过程</button><button v-if="!['succeeded','degraded','failed','cancelled'].includes(task.status)" @click="cancel" :disabled="busy">取消并释放</button><button v-if="task.status==='awaiting_confirmation'" class="primary" @click="confirmGeneration" :disabled="busy||(draft.needs_review&&!accept)">确认方案，开始制作 →</button><template v-if="finished"><button @click="download('md')" :disabled="busy">教案 MD ↓</button><button v-if="task.type!=='animation'" @click="save" :disabled="busy">免费保存并重导出</button><button class="primary" @click="download(task.type==='animation'?'mp4':'pptx')" :disabled="busy">{{task.type==='animation'?'预览 / 下载 MP4':'下载 PPTX'}} ↓</button></template></div></div>
      </section></div>
    </template>
    <template v-else-if="page==='knowledge'"><div class="page-heading"><div><div class="eyebrow">A SHARED FOUNDATION</div><h1>好课，有据可依。</h1><p>企业共享知识库。上传原文，保留出处，按需检索。</p></div><label v-if="can('kb.manage')" class="button primary">＋ 导入文档<input type="file" accept=".pdf,.docx,.pptx,.txt,.md" @change="upload" :disabled="busy" class="file-input"></label></div><div class="two-columns"><section class="panel padded"><h2>资料库 <small>{{docs.length}} 份文档</small></h2><p class="fine">PDF（文字版）/ DOCX / PPTX / TXT / MD · 单份不超过20MB</p><div v-if="!docs.length" class="empty-small">还没有资料，先上传一份教研文档。</div><article v-for="d in docs" :key="d.id" class="document-row"><span class="doc-icon">▤</span><div><h3>{{d.name}}</h3><small>{{({ready:'已就绪',pending:'排队中',indexing:'解析入库中',failed:'解析失败'})[d.status]||d.status}} · {{d.chunks}} 个切片 · {{date(d.created_at)}}</small></div><button v-if="can('kb.manage')&&d.status==='failed'" @click="run(async()=>{await api('/documents/'+d.id+'/retry','POST',{});docs=await api('/documents')})" :disabled="busy">重试</button><button v-if="can('kb.manage')" @click="removeDoc(d.id)" :disabled="busy">删除</button></article></section><section class="panel padded"><h2>检索测试</h2><form class="inline-form" @submit.prevent="search"><input v-model="query" placeholder="输入知识点，如：浮力" required><button class="primary" :disabled="busy">检索</button></form><article v-for="s in sources" :key="s.id" class="source-card"><div><h3>{{s.title}}</h3><small>{{s.location}}</small><p v-if="s.filter" class="fine">{{s.filter.method.includes("vector-candidate")?"向量候选，未按关键词删段":`相关段落保留 ${s.filter.kept} / ${s.filter.total}`}} · {{s.filter.method.includes("rerank")?"已语义重排":s.filter.method.includes("vector-candidate")?"未启用语义重排":"关键词与上下文筛选"}} · 非事实可信度评分<span v-if="s.filter.truncated"> · 篇幅受限，请查看原文</span></p><p>{{s.content}}</p></div></article><hr><h2>公开网页入库</h2><p class="fine">先抓取预览，再确认加入企业知识库。</p><form class="inline-form" @submit.prevent="importPage(false)"><input type="url" v-model="url" placeholder="https://…" required><button :disabled="busy||!can('kb.manage')">预览</button></form><div v-if="webPreview" class="web-preview"><h3>{{webPreview.title}}</h3><pre>{{webPreview.preview}}</pre><button class="primary" @click="importPage(true)" :disabled="busy">确认入库</button></div></section></div></template>
    <template v-else-if="page==='tasks'">
     <div class="page-heading"><div><div class="eyebrow">YOUR TEACHING COLLECTION</div><h1>每次思考，都有留存。</h1><p>查找、编辑与管理你的课件和教学动画。作品仅本人可见。</p></div><div class="collection-create"><button @click="newWork('animation')">＋ 新建动画</button><button class="primary" @click="newWork('courseware')">＋ 新建课件</button></div></div>
     <form class="panel works-toolbar" @submit.prevent="run(()=>loadWorks(true))"><label>作品视图<select v-model="worksView" aria-label="作品视图" :disabled="busy||health.works_view_version!=='views-v1'" @change="worksStatus='';run(()=>loadWorks(true))"><option value="works">当前作品</option><option value="interrupted">待处理与已取消</option><option value="history">全部记录（含历次重试）</option></select></label><label class="works-search">搜索作品<input v-model="worksQuery" type="search" placeholder="搜索作品名称或课题" maxlength="100"></label><label>作品类型<select v-model="worksType" @change="run(()=>loadWorks(true))"><option value="">全部类型</option><option value="courseware">课件</option><option value="animation">动画</option><option value="revision">单页修改</option></select></label><label>制作状态<select v-model="worksStatus" aria-label="制作状态" @change="run(()=>loadWorks(true))"><option value="">全部状态</option><option v-for="(label,key) in worksStatusOptions" :key="key" :value="key">{{label}}</option></select></label><button class="primary" :disabled="worksLoading||busy">{{worksLoading?'查询中…':'查询'}}</button><button type="button" :disabled="busy" @click="worksView='works';worksQuery='';worksType='';worksStatus='';run(()=>loadWorks(true))">重置</button></form>
     <p v-if="health.works_view_version!=='views-v1'" class="alert" role="status">作品收纳功能需要重启后端后生效，目前仍展示全部记录，不会删除作品。重启并刷新后可按视图收纳。</p>
     <p class="fine works-view-note">{{worksView==='history'?'这里保留历次制作记录，可查看原因或手动删除；积分明细仍保留在账单中。':worksView==='interrupted'?'中断或取消的作品集中在这里。同一课件续作只显示最新一次，可打开查看原因或继续制作。':'展示制作中、待审核及已完成的作品。中断和取消记录收纳在「待处理与已取消」，同一课件续作只显示最新一次。'}}</p>
     <div class="task-grid"><article v-for="t in workItems" :key="t.id" class="panel task-card" :data-task-id="t.id"><button class="task-open" @click="openWork(t)" :aria-label="'打开作品 '+(t.display_title||t.input.topic)"><div :class="['task-art',t.input.theme||'forest']"><span>{{t.type==='animation'?'◈':'▤'}}</span><small>{{t.mode==='sample'?'本地示例':'AI生成'}}</small><b>{{t.display_title||t.input.topic}}</b></div><div class="task-card-body"><span :class="['status',t.status]">{{statusText(t)}}</span><h3>{{t.display_title||t.input.topic}}</h3><p>{{t.type==='animation'?'教学动画':t.type==='revision'?'单页修改':'可编辑课件'}} · {{t.cost}} 积分</p><small>{{date(t.created_at)}}</small></div></button><div class="work-actions"><button @click="openWork(t)">{{t.status==='awaiting_confirmation'?'审核方案':t.type==='courseware'&&t.status==='succeeded'?'查看 / 编辑':'查看进度'}}</button><button @click="renameItem=t;renameTitle=t.display_title||t.input.topic" :disabled="busy">重命名</button><button class="danger-link" @click="deleteItem=t" :disabled="busy||!terminal.includes(t.status)" :title="terminal.includes(t.status)?'删除此作品':'请先打开作品并取消任务，再删除'">删除</button></div></article></div>
     <p v-if="!workItems.length&&!worksLoading" class="empty-small">{{worksQuery||worksType||worksStatus?'没有找到匹配的作品，试试其他筛选条件。':worksView==='works'?'当前没有制作中、待审核或已完成的作品。中断的作品可切换至「待处理与已取消」查看。':worksView==='interrupted'?'没有待处理或已取消的作品。':'暂无制作记录。'}}</p><div class="works-pagination"><button :disabled="!worksOffset||worksLoading" @click="worksOffset-=50;run(()=>loadWorks())">上一页</button><span>第 {{worksOffset/50+1}} 页</span><button :disabled="!worksMore||worksLoading" @click="worksOffset+=50;run(()=>loadWorks())">下一页</button></div>
    </template>
    <template v-else-if="page==='billing'"><div class="page-heading"><div><div class="eyebrow">SIMPLE & TRANSPARENT</div><h1>每一份投入，都清清楚楚。</h1><p>成员独立积分 · 无周期清零 · 仅模拟支付 · {{billing.plan?'基础套餐已开通':'尚未开通套餐'}}</p></div></div><div class="stat-grid"><div class="panel stat"><span>可用积分</span><strong>{{billing.available}}</strong><small>用于发起新的创作</small></div><div class="panel stat"><span>预留积分</span><strong>{{billing.reserved}}</strong><small>待确认或制作中的任务</small></div><div class="panel stat"><span>账户余额</span><strong>{{billing.balance}}</strong><small>余额 = 可用 + 预留</small></div></div><div class="two-columns product-grid"><section class="panel product" v-for="p in billing.products" :key="p.id"><span class="eyebrow">{{p.id==='basic'?'START CREATING':'KEEP EXPLORING'}}</span><h2>{{p.name}}</h2><strong>{{p.points}} <small>积分</small></strong><p>¥{{(p.amount_cents/100).toFixed(2)}} · 演示定价</p><button class="primary" @click="buy(p.id)" :disabled="busy">模拟购买（不真实扣款）</button></section></div><section class="panel padded"><h2>业务账单</h2><div class="table-scroll"><table><thead><tr><th>时间</th><th>订单</th><th>积分</th><th>金额</th><th>状态</th></tr></thead><tbody><tr v-for="o in billing.orders" :key="o.id"><td>{{date(o.created_at)}}</td><td>{{o.sku==='basic'?'基础套餐':'积分加量包'}}</td><td>+{{o.points}}</td><td>¥{{(o.amount_cents/100).toFixed(2)}}</td><td><button v-if="o.status==='pending'" @click="pay(o.id)">完成模拟支付</button><span v-else>模拟已支付</span></td></tr></tbody></table></div><h2 class="spaced">积分明细</h2><div class="table-scroll"><table><thead><tr><th>时间</th><th>类型</th><th>变动</th><th>变动后余额</th></tr></thead><tbody><tr v-for="l in billing.ledger" :key="l.id"><td>{{date(l.created_at)}}</td><td>{{({purchase:'模拟购买',settle:'生成结算',release:'预留释放',reserve:'任务预留'})[l.kind]||l.kind}}</td><td>{{l.delta>0?'+':''}}{{l.delta}}</td><td>{{l.balance_after}}</td></tr></tbody></table></div></section></template>
    <AccountSettings v-else-if="page==='account'" :api="api" @renamed="me.name=$event" @password-changed="passwordChanged"/>
    <template v-else-if="page==='admin'"><div class="page-heading"><div><div class="eyebrow">GROW TOGETHER</div><h1>一起教研，各自从容。</h1><p>管理企业成员与权限；个人作品仍归创作者私有。</p></div></div><section class="panel padded"><h2>新增成员</h2><form class="member-form" @submit.prevent="addMember"><label>账号<input v-model="newMember.username" required placeholder="3–40位字母数字"></label><label>姓名<input v-model="newMember.name" required maxlength="30"></label><label>初始密码<input v-model="newMember.password" type="password" required minlength="10" autocomplete="new-password"></label><button class="primary" :disabled="busy">创建成员</button></form><div class="table-scroll"><table><thead><tr><th>成员</th><th>角色</th><th>余额 / 预留</th><th>可用功能</th><th>启用</th><th></th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td>{{m.display_name}}<small class="block">{{m.username}}</small></td><td>{{m.role==='admin'?'管理员':'教师'}}</td><td>{{m.balance}} / {{m.reserved}}</td><td><label v-for="p in [['courseware.generate','课件'],['animation.render','动画'],['kb.manage','知识库']]" :key="p[0]" class="inline-check"><input type="checkbox" v-model="m.permissions" :value="p[0]" :disabled="m.role==='admin'">{{p[1]}}</label></td><td><input type="checkbox" v-model="m.active" :disabled="m.role==='admin'" :aria-label="'启用'+m.display_name"></td><td><button v-if="m.role!=='admin'" @click="updateMember(m)" :disabled="busy">保存</button><button v-if="can('billing.manage')" @click="assignPackage(m,'basic')" :disabled="busy">分配基础套餐</button></td></tr></tbody></table></div></section></template>
    <template v-else-if="page==='dashboard'"><div class="page-heading"><div><div class="eyebrow">OBSERVE & IMPROVE</div><h1>看见过程，持续精进。</h1><p>{{me.role==='admin'?'当前企业汇总':'仅本人成员数据'}} · 调用用量与业务积分分开记录</p></div></div><div class="stat-grid"><div class="panel stat"><span>任务数量</span><strong>{{dashboard.tasks.reduce((s,x)=>s+x.count,0)}}</strong><small>含未完成与取消任务</small></div><div class="panel stat"><span>模型调用P95</span><strong>{{(dashboard.p95_ms/1000||0).toFixed(1)}}<small> 秒</small></strong><small>无调用时显示0</small></div><div class="panel stat"><span>当前模式</span><strong class="smaller">{{health.mode==='sample'?'本地示例':'真实接口'}}</strong><small>示例不会产生模型费用</small></div></div><section class="panel padded"><h2>调用记录</h2><div class="table-scroll"><table><thead><tr><th>时间</th><th>操作</th><th>模型</th><th>输入 / 输出Token</th><th>耗时</th><th>结果</th></tr></thead><tbody><tr v-for="(l,i) in dashboard.usage" :key="i"><td>{{date(l.created_at)}}</td><td>{{l.operation}}</td><td>{{l.model}}</td><td>{{l.input_tokens}} / {{l.output_tokens}}</td><td>{{l.latency_ms}}ms</td><td>{{l.success?'成功':'失败'}}</td></tr></tbody></table></div><p v-if="!dashboard.usage.length" class="empty-small">暂无真实模型调用。示例模式不伪造Token或成本。</p></section><section v-if="can('eval.run')" class="panel padded spaced"><h2>知识检索评测</h2><p class="fine">使用固定标注集检查来源召回；不将模型自评当作事实证明。</p><button @click="evaluate" :disabled="busy">运行小样本评测</button></section></template>
    <footer class="page-footer"><span>备课工坊 · 为真正的教学而设计</span><span>AI内容需教师审核 · 当前版本 0.1</span></footer>
   </div>
  </main>
  <div v-if="renameItem||deleteItem" class="modal-backdrop" @click.self="!busy&&(renameItem=null,deleteItem=null)"><section class="work-dialog" role="dialog" aria-modal="true" :aria-label="renameItem?'重命名作品':'删除作品'" @keydown="trapDialog" @keydown.esc="!busy&&(renameItem=null,deleteItem=null)"><form v-if="renameItem" @submit.prevent="renameWork"><h2>重命名作品</h2><p class="fine">修改作品列表名称；课件内的页面内容可在编辑器中修改。</p><label>作品名称<input v-model="renameTitle" maxlength="100" required autofocus></label><div class="action-row"><button type="button" @click="renameItem=null" :disabled="busy">取消</button><button class="primary" :disabled="busy||!renameTitle.trim()">保存名称</button></div></form><template v-else><h2>删除“{{deleteItem.display_title||deleteItem.input.topic}}”？</h2><p>删除后无法再从作品列表查看或下载。已结算积分不退回，历史账单保留。</p><div class="action-row"><button @click="deleteItem=null" :disabled="busy">保留作品</button><button class="danger" @click="deleteWork" :disabled="busy">确认删除</button></div></template></section></div>
  <div v-if="showProcess" class="modal-backdrop" @click.self="showProcess=false"><section class="process-dialog" role="dialog" aria-modal="true" aria-label="制作过程" @keydown.esc="showProcess=false" @keydown="trapDialog"><div class="panel-title"><div><span class="eyebrow">BEHIND THE LESSON</span><h2>每一步，都有迹可循。</h2></div><button autofocus @click="showProcess=false" aria-label="关闭过程">×</button></div><details v-for="group in processGroups" :key="group.stage" open><summary>{{group.title}}</summary><div v-for="ev in group.events" :key="ev.id" class="event"><span>{{date(ev.created_at)}}</span><p>{{ev.message}}</p></div></details><details v-if="task.result?.script"><summary>动画代码</summary><pre class="code-preview">{{task.result.script}}</pre></details><p class="fine">流水号 {{task.id}} · 修订 {{task.revision}} · {{task.charge_state==='settled'?'已结算':task.charge_state==='released'?'已释放':'预留中'}}</p></section></div>
 </div>
</template>
